import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { SAMPLE_VIDEO } from '../data';
import './AuthForms.css';

export default function Signup({ onSignup }) {
  const navigate = useNavigate();
  const [form, setForm] = useState({
    name: '',
    age: '',
    email: '',
    password: '',
  });
  const [role, setRole] = useState('student');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const handleChange = (e) =>
    setForm((prev) => ({ ...prev, [e.target.name]: e.target.value }));

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    // Validation
    if (role === 'student' && !form.age) {
      return setError('Please enter your age for student signup.');
    }
    if (role === 'staff' && form.age) {
      return setError('Staff signup should not include age.');
    }

    try {
      const res = await fetch('http://localhost:5000/api/auth/signup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...form, role }),
      });

      const data = await res.json();

      if (res.ok && data.user) {
        localStorage.setItem('token', data.token || '');
        localStorage.setItem('role', role);
        localStorage.setItem('user', JSON.stringify(data.user));

        setSuccess('Account created successfully!');
        onSignup(data.user);

        setTimeout(() => {
          if (role === 'staff') navigate('/staff-dashboard');
          else navigate('/dashboard');
        }, 800);
      } else {
        setError(data.message || 'Failed to create account.');
      }
    } catch (err) {
      console.error('Signup error:', err);
      setError('Something went wrong. Please try again.');
    }
  };

  return (
    <div className={'auth-page ${role}'}>
      <div className="video-bg" aria-hidden>
        <video autoPlay muted loop playsInline>
          <source src={SAMPLE_VIDEO} type="video/mp4" />
        </video>
        <div className="overlay" />
      </div>

      <div className="auth-container">
        {/* Welcome Banner */}
        <div className="welcome-banner">
          <h1>
            🍃 <span>WELCOME TO</span> <span className="brand">NEXORA</span> 🍃
          </h1>
        </div>

        {/* Role Toggle */}
        <div className="role-toggle">
          <button
            type="button"
            className={role === 'student' ? 'active' : ''}
            onClick={() => setRole('student')}
          >
            Student
          </button>
          <button
            type="button"
            className={role === 'staff' ? 'active' : ''}
            onClick={() => setRole('staff')}
          >
            Staff
          </button>
        </div>

        {/* Auth Card */}
        <div className="auth-card">
          <h2 className="role-heading">
            {role === 'student' ? 'Student Signup' : 'Staff Signup'}
          </h2>

          <form className="form" onSubmit={handleSubmit}>
            <input
              className="input"
              name="name"
              placeholder={role === 'student' ? 'Student Name' : 'Staff Name'}
              value={form.name}
              onChange={handleChange}
              required
            />

            <input
              className="input"
              name="email"
              type="email"
              placeholder={
                role === 'student' ? 'student@school.edu' : 'staff@school.edu'
              }
              value={form.email}
              onChange={handleChange}
              required
            />

            {role === 'student' && (
              <input
                className="input"
                name="age"
                type="number"
                placeholder="Age"
                value={form.age}
                onChange={handleChange}
                required
              />
            )}

            <input
              className="input"
              name="password"
              type="password"
              placeholder="Password"
              value={form.password}
              onChange={handleChange}
              required
            />

            <button className="btn btn-primary" type="submit">
              Sign up
            </button>

            {error && <p className="error">{error}</p>}
            {success && <p className="success">{success}</p>}
          </form>
        </div>
      </div>
    </div>
  );
}
